/*
 * Design tokens: the one source of truth for colour, type, space, shape and motion.
 *
 * Names follow Hallmark's token roles (https://github.com/nutlope/hallmark,
 * references/export-formats.md), so a Hallmark run (the design-language skill)
 * rewrites the values in this file and every component follows. tokens.stylex.ts
 * points StyleX at these variables; components never use a raw value.
 *
 * Neutral starter values: no design language has been chosen yet.
 * Each colour is written once as light-dark(<light>, <dark>). The OS setting picks
 * one; data-theme="light" or "dark" on any element (usually <html>) pins it.
 */
:root {
  color-scheme: light dark;
}
[data-theme='light'] {
  color-scheme: light;
}
[data-theme='dark'] {
  color-scheme: dark;
}

:root {
  --color-paper: light-dark(#ffffff, #0b0b0f);
  --color-paper-2: light-dark(#fafafa, #141418);
  --color-paper-3: light-dark(#f4f4f5, #1f1f25);
  --color-ink: light-dark(#18181b, #f4f4f5);
  --color-ink-2: light-dark(#3f3f46, #d4d4d8);
  --color-muted: light-dark(#5f5f6b, #a1a1aa);
  --color-rule: light-dark(#e4e4e7, #2b2b33);
  --color-rule-2: light-dark(#d4d4d8, #3a3a44);
  --color-accent: light-dark(#18181b, #f4f4f5);
  --color-accent-ink: light-dark(#ffffff, #0b0b0f);
  --color-focus: light-dark(#2563eb, #60a5fa);
  --color-error: light-dark(#dc2626, #f87171);
  --color-error-ink: light-dark(#ffffff, #0b0b0f);
  --color-success: light-dark(#15803d, #4ade80);
  --shadow-color: light-dark(rgb(24 24 27 / 0.08), rgb(0 0 0 / 0.5));

  /* Derived from the roles above, so a new palette carries them along. */
  --color-accent-hover: color-mix(in oklch, var(--color-accent), var(--color-paper) 15%);
  --color-secondary-hover: color-mix(in oklch, var(--color-paper-3), var(--color-ink) 6%);
  --color-error-hover: color-mix(in oklch, var(--color-error), var(--color-ink) 15%);
  --color-overlay: color-mix(in oklch, var(--color-ink) 40%, transparent);
  --shadow-card: 0 1px 2px var(--shadow-color);
  --shadow-pop: 0 4px 12px var(--shadow-color), 0 1px 3px var(--shadow-color);
  --shadow-modal: 0 12px 32px var(--shadow-color);
}

/* Theme-independent: Hallmark's app-screen scale plus the project's extra roles. */
:root {
  --font-display: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-body: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-mono: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  --weight-normal: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;
  --leading-tight: 1.25;
  --leading-normal: 1.5;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-md: 1rem;
  --text-lg: 1.2rem;
  --text-xl: 1.44rem;
  --text-2xl: 1.728rem;
  --text-3xl: 2.074rem;

  --space-3xs: 2px;
  --space-2xs: 4px;
  --space-xs: 8px;
  --space-sm: 12px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 40px;
  --space-2xl: 64px;
  --space-3xl: 96px;
  --space-4xl: 144px;
  --control-sm: 32px;
  --control: 36px;
  --control-lg: 40px;

  --radius-inner: 4px;
  --radius-control: 6px;
  --radius-card: 10px;
  --radius-pill: 999px;
  --rule-hair: 1px;

  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in: cubic-bezier(0.7, 0, 0.84, 0);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --dur-micro: 120ms;
  --dur-short: 220ms;
  --dur-long: 420ms;

  --z-dropdown: 100;
  --z-modal: 400;
  --z-toast: 500;
  --z-tooltip: 600;
}

/*
 * Light and dark come from tokens.css. 'system' (no data-theme) follows the OS;
 * applyTheme pins a theme by setting data-theme on <html>, so portalled popups
 * (dialogs, menus, toasts) follow it too.
 */
export const themeNames = ['light', 'dark'] as const;
export type ThemeName = (typeof themeNames)[number];
export type ThemeChoice = ThemeName | 'system';

export const isThemeName = (value: unknown): value is ThemeName =>
  (themeNames as readonly unknown[]).includes(value);

export function applyTheme(choice: ThemeChoice): void {
  const root = document.documentElement;
  if (choice === 'system') delete root.dataset.theme;
  else root.dataset.theme = choice;
}

/** The theme on screen now: the pinned one, else the OS setting. */
export function effectiveTheme(): ThemeName {
  const pinned = document.documentElement.dataset.theme;
  if (isThemeName(pinned)) return pinned;
  return matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

import * as stylex from '@stylexjs/stylex';
import type { CompiledStyles, InlineStyles, StyleXArray } from '@stylexjs/stylex';

/** Anything stylex.props accepts: compiled styles (or arrays of them), false, null or undefined. */
export type Style = StyleXArray<
  CompiledStyles | boolean | null | undefined | Readonly<[CompiledStyles, InlineStyles]>
>;

/**
 * Turns StyleX styles into a Base UI className. Base UI passes the
 * component's state (open, checked, disabled…) so styles can depend on it:
 *   className={cx((s) => [styles.root, s.checked && styles.checked], props.style)}
 * `extra` is the caller's own StyleX override, applied last.
 */
export function cx<State>(fn: (state: State) => Style[], extra?: Style): (state: State) => string {
  return (state) => stylex.props(...fn(state), extra).className ?? '';
}

/** Spreads StyleX styles plus an optional caller override onto a plain element. */
export function sx(...styles: Style[]): {
  className?: string;
  style?: Record<string, string | number>;
} {
  const { className, style } = stylex.props(...styles);
  return { ...(className ? { className } : {}), ...(style ? { style } : {}) };
}

/** Static StyleX styles as a className string, for parts whose look never depends on state. */
export function cls(...styles: Style[]): string {
  return stylex.props(...styles).className ?? '';
}

/** The `xstyle` prop every component takes: a StyleX override, applied last. */
export type Override = { xstyle?: Style };

/** Base UI's state for parts that animate in and out. */
export type Transition = { transitionStatus?: 'starting' | 'ending' | 'idle' | undefined };

/** True while a popup is animating in or out. */
export const isTransitioning = (s: Transition): boolean =>
  s.transitionStatus !== undefined && s.transitionStatus !== 'idle';

import { render, type RenderResult } from '@testing-library/react';
import type { ReactElement } from 'react';
import { applyTheme, themeNames, type ThemeName } from '@/styles/themes';
import '@/styles/tokens.css';
import '@/styles/tokens.stylex';

/**
 * Renders `ui` under each theme in turn and runs `check` on it, so one test
 * covers light and dark. The theme is pinned on <html>, as the app does, so
 * portalled popups see it too. Each render is unmounted before the next, so
 * `screen` queries see one copy at a time.
 */
export async function forEachTheme(
  ui: () => ReactElement,
  check: (result: RenderResult, theme: ThemeName) => void | Promise<void>,
): Promise<void> {
  for (const theme of themeNames) {
    applyTheme(theme);
    const result = render(ui());
    try {
      await check(result, theme);
    } finally {
      result.unmount();
      applyTheme('system');
    }
  }
}
